using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class CombatTests {
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
    public static void Run(string root){
        using var doc=JsonDocument.Parse(File.ReadAllText(PackageLayout.FromBase("Content/Data/combat_rules.json")));int compared=0;
        foreach(var v in doc.RootElement.GetProperty("vectors").EnumerateArray()){int N(string n)=>v.GetProperty(n).GetInt32();int actual=Math.Max(0,N("hp")-CombatMath.Damage(N("basis"),N("attack"),N("bonus"),N("captain"),N("armor"),N("defense"),N("flag")));if(actual!=N("expected"))throw new Exception("Native damage vector mismatch");compared++;}
        Check(compared==1426,"1426 C# damage results match original x86 fixtures, including signed-byte edges");
        Check(CombatMath.Damage(20,0,0,0,20,0)==0&&CombatMath.Damage(20,0,0,0,21,0)==1,"zero damage and negative intermediate remain distinct");
        var visual=new VisualCatalog();Check(visual.AttackVisual.FrameCount==10&&visual.AttackVisual.FrameDelay==2&&visual.AttackVisual.Frames.Count==160&&visual.AttackVisual.Frames.All(f=>f.Commands.Count==2&&f.Commands.Any(c=>c.Kind=="unit"&&c.Sprite>=1346&&c.Sprite<4194)),"original attack catalog has sixteen directions, ten phases and original timing metadata");var pose=new Actor{Type=0,Direction=9,AttackTarget=1,AttackCooldown=20};var first=visual.Frame(pose);pose.AttackCooldown=1;Check(!first.SequenceEqual(visual.Frame(pose)),"combat renderer advances from first to last original attack pose");
        Simulation Create(){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA"));new VisualCatalog().Apply(w);return new Simulation(Simulation.TrainingWorld(w));}
        var sim=Create();var a=sim.World.Units.First(u=>u.Type==0&&u.Owner==0);var b=sim.World.Units.Last();
        Check(sim.Attack(a,b),"swordsman accepts explicit enemy target in separate training scenario");
        for(int i=0;i<25;i++)sim.Step();string midway=sim.Serialize();var resumed=Create();resumed.Restore(midway);
        for(int i=0;i<400;i++){sim.Step();resumed.Step();}
        Check(sim.Serialize()==resumed.Serialize(),"pursuit, retaliation and combat timers resume deterministically");
        Check(b.Health==0&&a.Health>0&&!VisualCatalog.Visible(b)&&a.AttackTarget==-1,"melee resolves defeat, clears target and hides defeated actor");
        Check(!sim.Attack(a,b)&&!sim.Order(b,b.X/1024,b.Y/1024),"defeated units cannot attack, receive movement or be targeted");
        var fresh=Create();fresh.Restore(sim.Serialize());Check(fresh.Serialize()==sim.Serialize(),"post-combat save restores into a fresh training scene");
        var blocked=Create();var x=blocked.World.Units.First(u=>u.Type==0&&u.Owner==0);var y=blocked.World.Units.Last();y.X=x.X+1024;y.Y=x.Y;blocked.Attack(x,y);for(int i=0;i<12;i++)blocked.Step();int hp=y.Health;blocked.Step();Check(y.Health==hp,"reload prevents damage on consecutive ticks");blocked.Stop(x);Check(x.AttackTarget<0&&!x.AutomaticDefense,"stop immediately cancels the current attack");int old=y.Health;for(int i=0;i<25;i++)blocked.Step();Check(y.Health<old&&x.LastAttacker==y.Slot,"stopped troop defends itself when attacked again");
        var protectedSim=Create();var fighter=protectedSim.World.Units.First(u=>u.Type==0&&u.Owner==0);var farmer=protectedSim.World.Units.First(u=>u.Type==5&&u.Owner==0);Check(!protectedSim.Attack(fighter,farmer)&&!protectedSim.Attack(farmer,protectedSim.World.Units.Last()),"friendly fire and unsupported attacker roles rejected");
        foreach(var mutation in new Action<JsonNode>[]{n=>n["Units"]![0]!["Health"]=999999,n=>n["Units"]![0]!["AttackTarget"]=999999,n=>n["Units"]![0]!["AttackCooldown"]=-1}){var node=JsonNode.Parse(midway)!;mutation(node);string before=fresh.Serialize();try{fresh.Restore(node.ToJsonString());throw new Exception("Invalid combat accepted");}catch(InvalidDataException){}Check(fresh.Serialize()==before,"malformed combat save rejected without changing world");}
        var economy=Create();var foe=economy.World.Units.Last();foe.LegacyState=14;var worker=economy.World.Units.First(u=>u.Type==5&&u.Owner==0);economy.Gather(worker,5642);for(int i=0;i<2000&&worker.Food==0;i++)economy.Step();Check(worker.Food==1,"combat integration fixture collects actual food before attack");foe.LegacyState=7;foe.X=worker.X;foe.Y=worker.Y;foe.AttackTarget=worker.Slot;worker.Health=1;for(int i=0;i<12;i++)economy.Step();var economyCopy=Create();economyCopy.Restore(economy.Serialize());Check(worker.Health==0&&worker.FoodJob==0&&worker.Route.Count==0&&worker.Food==1&&economyCopy.Serialize()==economy.Serialize(),"defeated carrier stops work and retains accounted cargo across save/load");
        var construction=Create();var builder=construction.World.Units.First(u=>u.Type==7&&u.Owner==0);bool started=false;for(int yy=8;yy<22&&!started;yy++)for(int xx=20;xx<29&&!started;xx++)started=construction.StartConstruction(builder,3,yy*256+xx);Check(started,"combat integration fixture starts a paid building");var attacker=construction.World.Units.Last();attacker.X=builder.X;attacker.Y=builder.Y;attacker.AttackTarget=builder.Slot;builder.Health=1;for(int i=0;i<12;i++)construction.Step();Check(builder.Health==0&&construction.Constructions[0].BuilderSlot==-1&&construction.World.Resources[0]==20,"builder defeat pauses paid construction without refund or lost site");var loadedConstruction=Create();loadedConstruction.Restore(construction.Serialize());Check(loadedConstruction.Serialize()==construction.Serialize(),"paused construction caused by combat survives save/load");
        var ordinary=new Simulation(LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA")));var oldSave=JsonNode.Parse(ordinary.Serialize())!;oldSave["Version"]=4;foreach(var actor in oldSave["Units"]!.AsArray()){actor!.AsObject().Remove("AttackTarget");actor.AsObject().Remove("AttackCooldown");actor.AsObject().Remove("HitFlash");}ordinary.Restore(oldSave.ToJsonString());Check(ordinary.World.Units.All(u=>u.AttackTarget==-1),"v4 saves migrate with no combat orders");
    }
}
